-- LD-DOC-r5 (stream A, part 2): every remaining dropdown list of the screens joins the administrator's catalogue.
-- Generated by tools/lists/gen.py from the screens' own message files, so each label is the one the screen shows today
-- and each code is the one already stored. Additive: no record table changes except the two CHECKs below.
--
-- Class "b" lists (system = true) take label and order edits only: system logic depends on their codes (see
-- docs/design/LD-DOC-13-admin-lists.md). Class "a" lists (system = false) take new options; their fixed CHECK is replaced
-- by a format check here and a catalogue check in the service.

alter table claim alter column kind type varchar(60);
alter table claim_revision alter column kind type varchar(60);
alter table evidence_item alter column importance type varchar(60);
alter table claim drop constraint claim_kind_known;
alter table claim add constraint claim_kind_format check (kind ~ '^[A-Z][A-Z0-9_]*$');
alter table evidence_item drop constraint evidence_importance_known;
alter table evidence_item add constraint evidence_importance_format check (importance is null or importance ~ '^[A-Z][A-Z0-9_]*$');

insert into lookup_value (list_code, code, label_ar, label_en, origin, approved_by, approved_at, sort_order, system,
                          created_by, updated_by)
