    ('ACCESS_SCOPE_TYPE', 'ALL', 'كل القضايا غير الحساسة (مستوى الإدارة)', 'All non-restricted cases (department level)', 1, true),
    ('ACCESS_SCOPE_TYPE', 'ORG_UNIT', 'وحدة والوحدات التابعة لها', 'A unit and the units below it', 2, true),
